--
-- Table structure for table `mouvements_lits`
--

DROP TABLE IF EXISTS `mouvements_lits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mouvements_lits` (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `lit_id` int NOT NULL,
  `type_mouvement` enum('ADMISSION','TRANSFERT','SORTIE') NOT NULL,
  `date_mouvement` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `user_id` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_id` (`patient_id`),
  KEY `lit_id` (`lit_id`),
  CONSTRAINT `mouvements_lits_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`),
  CONSTRAINT `mouvements_lits_ibfk_2` FOREIGN KEY (`lit_id`) REFERENCES `lits` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
