INSERT INTO `reevaluations_hospitalisees` VALUES (7,6,1,43,'2026-05-05','10:10:38','Asthénie, Fièvre, Prurit',NULL,'x\r\nÉtat général conservé. Conscient, orienté temporo-spatialement. Bien hydraté. Conjonctives rosées. Pas de pâleur ni ictère.',NULL,NULL,NULL,NULL,NULL,NULL,'AMELIORATION_PARTIELLE',NULL,'xxx',NULL,'xxx','• Prévention escarres\r\n• Hydratation orale encouragée\r\n• Régime hypocalorique',2,'2026-05-05 09:10:38'),(8,6,1,43,'2026-05-14','11:31:05','Œdèmes, Fièvre, Prurit',NULL,'État général conservé. Conscient, orienté temporo-spatialement. Bien hydraté. Conjonctives rosées. Pas de pâleur ni ictère.','Bruits du cœur réguliers, bien frappés, sans souffle audible. Pouls bien perçu, symétrique. TA stable. Pas d\'œdèmes des membres inférieurs. TRC < 3s.',NULL,NULL,NULL,NULL,NULL,'FAVORABLE',NULL,'Bonsoir',NULL,'j,keb cqj cfdkdjbc sqdbcsd,q csznbdq kszdqvck szdkncvkl s cvksnd; cvkfxv k,n xvbk dsfqnxkldf vndfkj vdfkinv  kfdsvk ikfdbv','• Repos au lit',NULL,'2026-05-14 10:31:05'),(9,14,1,50,'2026-05-24','23:57:06',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FAVORABLE','Bon','palu grave',NULL,'Continuer avec artésunat',NULL,NULL,'2026-05-24 22:57:06'),(10,14,1,50,'2026-05-31','16:53:07','Asthénie, Prurit, Dyspnée, Toux, Fièvre',NULL,NULL,NULL,'Murmure vésiculaire présent bilatéral. Pas de râles crépitants ni sibilants. Fréquence respiratoire normale. Saturation en O₂ satisfaisante. Pas de signes de détresse respiratoire.',NULL,NULL,NULL,NULL,'AMELIORATION_PARTIELLE','L\'état général du patient et vous plutôt bien','dgfb',NULL,'Continuez avec le traitement en cours.','• Régime diabétique',NULL,'2026-05-31 15:53:07'),(11,14,1,50,'2026-05-31','17:46:47','Asthénie',NULL,NULL,NULL,'Murmure vésiculaire présent bilatéral. Pas de râles crépitants ni sibilants. Fréquence respiratoire normale. Saturation en O₂ satisfaisante. Pas de signes de détresse respiratoire.',NULL,NULL,NULL,NULL,'FAVORABLE',NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-31 16:46:47'),(12,14,1,50,'2026-05-31','17:53:09','Asthénie',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FAVORABLE',NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-31 16:53:09'),(13,14,1,50,'2026-05-31','18:08:20','Œdèmes',NULL,NULL,'Bruits du cœur réguliers, bien frappés, sans souffle audible. Pouls bien perçu, symétrique. TA stable. Pas d\'œdèmes des membres inférieurs. TRC < 3s.',NULL,NULL,NULL,NULL,NULL,'FAVORABLE',NULL,NULL,NULL,NULL,NULL,NULL,'2026-05-31 17:08:20');
