DROP TABLE IF EXISTS `sage_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sage_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type_source` enum('CSV_FILE','ODBC_DSN','ODBC_MDB','SQLSERVER') NOT NULL DEFAULT 'CSV_FILE',
  `csv_watch_path` varchar(500) DEFAULT NULL,
  `csv_delimiter` varchar(5) DEFAULT ';',
  `csv_encoding` varchar(20) DEFAULT 'windows-1252',
  `odbc_dsn` varchar(100) DEFAULT NULL,
  `odbc_mdb_path` varchar(500) DEFAULT NULL,
  `sql_host` varchar(100) DEFAULT NULL,
  `sql_instance` varchar(100) DEFAULT NULL,
  `sql_db` varchar(100) DEFAULT 'GESCOM',
  `sage_user` varchar(100) DEFAULT '',
  `sage_password` varchar(255) DEFAULT '',
  `depot_no` int DEFAULT '1',
  `depot_intitule` varchar(100) DEFAULT 'PHARMACIE',
  `last_sync_at` datetime DEFAULT NULL,
  `last_sync_ok` tinyint(1) DEFAULT '0',
  `last_sync_msg` text,
  `last_csv_file` varchar(500) DEFAULT NULL,
  `articles_sage` int DEFAULT '0',
  `articles_mappes` int DEFAULT '0',
  `actif` tinyint(1) DEFAULT '1',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `pdftotext_path` varchar(500) DEFAULT NULL COMMENT 'Chemin vers pdftotext.exe (Poppler). Vide = détection automatique.',
  `python_path` varchar(500) DEFAULT NULL COMMENT 'Chemin manuel vers python.exe (override la detection automatique)',
  `auto_sync_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Activer la synchronisation automatique périodique',
  `sync_interval_min` int NOT NULL DEFAULT '60' COMMENT 'Intervalle en minutes entre deux synchronisations',
  `last_auto_sync_at` datetime DEFAULT NULL COMMENT 'Date de la dernière synchronisation automatique',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
